<?php
namespace backend\models; use yii\behaviors\TimestampBehavior; use yii\db\ActiveRecord; use yii\db\Expression;
class CompanyContact extends ActiveRecord { public static function tableName(){return 'company_contacts';} public function behaviors(){return [['class'=>TimestampBehavior::class,'value'=>new Expression('NOW()')]];} public function rules(){return [[['company_id','name','phone'],'required'],[['company_id','gender','religion_id'],'integer'],[['name','email'],'string','max'=>255],[['phone','phone_alternative'],'string','max'=>30],[['address'],'string'],[['honorific','degree'],'string','max'=>50],['email','email'],['company_id','exist','skipOnError'=>true,'targetClass'=>Company::class,'targetAttribute'=>['company_id'=>'id']]];} public function getCompany(){return $this->hasOne(Company::class,['id'=>'company_id']);} public function attributeLabels(){return ['company_id'=>'Perusahaan','name'=>'Nama Pegawai','phone'=>'No. Telp','phone_alternative'=>'No. Telp (Alternatif)','honorific'=>'Gelar Depan','degree'=>'Gelar Belakang','gender'=>'Jenis Kelamin','religion_id'=>'Agama','address'=>'Alamat','email'=>'Email'];}}
